// 兜底常量：宿主内联时同作用域已有同名 const，let 声明不冲突。
let E_STAGE = typeof STAGE !== 'undefined' ? STAGE : {
  PENDING: 'PENDING', RUNNING: 'RUNNING', COMPLETED: 'COMPLETED', FAILED: 'FAILED', STOPPED: 'STOPPED',
}
let E_TASK_STATUS = typeof TASK_STATUS !== 'undefined' ? TASK_STATUS : {
  PENDING: 'PENDING', RUNNING: 'RUNNING', DONE: 'DONE', FAILED: 'FAILED', SKIPPED: 'SKIPPED',
}

// Task 运行时快照（供 UI 消费的最小字段集）
function taskSnapshot(t) {
  return {
    id: t.id,
    name: t.name,
    type: t.type,
    dependsOn: t.dependsOn || [],
    status: t.status,
    processor: t.processor || null,       // 处理器技能绝对路径（Client 读取 skill 文本用）
    gateChecker: (t.gate && t.gate.checker) || null, // 门禁技能绝对路径
    gateResult: t.gateResult || null,
    gateOnFailure: t.gateOnFailure || null,
    retries: t.retries || 0,
    _loopGroup: t._loopGroup || null,
    _loopItem: t._loopItem || null,
    _loopIndex: t._loopIndex ?? 0,
    _loopGroupName: t._loopGroupName || null,
    _onError: t._onError || null,
    // Iter-8：并发组元数据（Client DAG 分组渲染）
    _concurrentGroup: t._concurrentGroup || null,
    _concurrentGroupName: t._concurrentGroupName || null,
    _concurrentItem: t._concurrentItem || null,
    _concurrentIndex: t._concurrentIndex ?? 0,
    _concurrentMax: t._concurrentMax || null,
  }
}

// 全局快照（供 RPC / Tool 返回；指纹用于 Client 防抖）
function createWorkflowEngine() {
  const state = {
    workflow: null, // 工作流名称
    version: null,
    description: null,
    params: {},
    maxConcurrency: 1, // Iter-7：工作流级最大并发数
    active: false, // 是否有进行中的实例
    stage: E_STAGE.PENDING,
    tasks: [], // Task 运行时状态数组
    gateResult: null, // 最近 Gate 结果（PASS/FAIL）
    retries: 0, // 最近任务的重试计数
    error: null,
    updatedAt: 0,
    logs: [], // 结构化执行日志 [{ts, action, detail}]
    persist: null, // 最近一次持久化结果
    def: null, // Iter-16：最近一次 begin 的解析定义（供 reset 重新 begin 用）
  }

  function fingerprint() {
    const t = state.tasks.map((x) => x.id + ':' + x.status).join(',')
    return [state.stage, state.gateResult || '', state.retries, state.error || '', t].join('|')
  }

  function snapshot() {
    return {
      workflow: state.workflow,
      version: state.version,
      description: state.description,
      maxConcurrency: state.maxConcurrency,
      active: state.active,
      stage: state.stage,
      tasks: state.tasks.map(taskSnapshot),
      gateResult: state.gateResult,
      retries: state.retries,
      error: state.error,
      updatedAt: state.updatedAt,
      logs: state.logs.slice(-200), // 最多保留最近 200 条
      persist: state.persist,
      runnable: getRunnableTasks(), // Iter-7：当前就绪可并发执行的任务
      fingerprint: fingerprint(),
    }
  }

  // 启动新工作流：清空旧状态，按解析结果初始化 N 个 Task
  function begin(parsed) {
    state.def = parsed // Iter-16：保留解析定义供 reset 重新 begin
    state.workflow = parsed.name
    state.version = parsed.version
    state.description = parsed.description
    state.params = parsed.params || {}
    state.maxConcurrency = parsed.maxConcurrency || 1 // Iter-7：工作流级最大并发数
    state.active = true
    state.stage = E_STAGE.PENDING
    state.gateResult = null
    state.retries = 0
    state.error = null
    state.logs = [] // Iter-6：重新 begin 时清除历史日志，避免跨实例残留
    state.tasks = parsed.tasks.map((t) => ({
      id: t.id,
      name: t.name,
      type: t.type,
      dependsOn: t.dependsOn || [], // Iter-7：前驱依赖，供 getRunnableTasks 计算就绪
      status: E_TASK_STATUS.PENDING,
      processor: t.processor || null, // 绝对路径（由 tools 层解析后写入）
      outputs: t.outputs || [],
      gate: t.gate || null, // {checker, onFailure, maxRetries}
      gateResult: null,
      retries: 0,
      _loopGroup: t._loopGroup || null,
      _loopItem: t._loopItem || null,
      _loopIndex: t._loopIndex ?? 0,
      _loopGroupName: t._loopGroupName || null,
      _onError: t._onError || null,
      // Iter-8：并发组元数据（engine 组级并发控制 + Client DAG 分组渲染）
      _concurrentGroup: t._concurrentGroup || null,
      _concurrentGroupName: t._concurrentGroupName || null,
      _concurrentItem: t._concurrentItem || null,
      _concurrentIndex: t._concurrentIndex ?? 0,
      _concurrentMax: t._concurrentMax || null,
    }))
    state.updatedAt = Date.now()
    log('BEGIN', '工作流 "' + state.workflow + '" 已初始化，tasks=' + state.tasks.length)
  }

  // 更新单个 Task 状态
  function updateTask(taskId, patch) {
    const t = state.tasks.find((x) => x.id === taskId)
    if (!t) return false
    if (patch.status !== undefined) t.status = patch.status
    if (patch.gateResult !== undefined) t.gateResult = patch.gateResult
    if (patch.retries !== undefined) t.retries = patch.retries
    if (patch.error !== undefined) t.error = patch.error
    state.updatedAt = Date.now()
    log('TASK', taskId + ' -> ' + t.status)
    // Iter-6：任务 FAILED 后按 _onError 处理循环中断
    //   break    → 同组后续 PENDING 迭代标记 SKIPPED（中断）
    //   continue → 不中断，后续迭代继续执行
    if (t.status === E_TASK_STATUS.FAILED && t._onError === 'break') {
      processBreak(taskId)
    }
    return true
  }

  // Iter-7：返回就绪任务列表（dependsOn 全部完成 + 受 max-concurrency 限制）。
  // 就绪 = 所有前驱均 DONE 或 SKIPPED（FAILED 前驱不放行）；
  // 可用并发槽位 = maxConcurrency - 当前 RUNNING 数。
  function getRunnableTasks() {
    // Iter-21：非 active（STOPPED/COMPLETED/FAILED）不派发任何任务——否则 STOPPED 后 agent 仍看到 runnable
    // 非空而继续驱动（subagent 返回后主 session 又被触发继续）。
    if (!state.active) return []
    const running = state.tasks.filter((t) => t.status === E_TASK_STATUS.RUNNING).length
    const slots = Math.max(0, state.maxConcurrency - running)
    if (slots === 0) return []
    const finished = new Set(
      state.tasks
        .filter((t) => t.status === E_TASK_STATUS.DONE || t.status === E_TASK_STATUS.SKIPPED)
        .map((t) => t.id)
    )
    // 预计算每个并发组：组内 RUNNING 数 + 组级 max（Iter-8）
    const gRun = new Map()
    const gMax = new Map()
    state.tasks.forEach((t) => {
      if (!t._concurrentGroup) return
      gRun.set(t._concurrentGroup, (gRun.get(t._concurrentGroup) || 0) + (t.status === E_TASK_STATUS.RUNNING ? 1 : 0))
      if (!gMax.has(t._concurrentGroup)) gMax.set(t._concurrentGroup, t._concurrentMax || 1)
    })
    const result = []
    for (const t of state.tasks) {
      if (result.length >= slots) break
      if (t.status !== E_TASK_STATUS.PENDING) continue
      const deps = t.dependsOn || []
      if (!deps.every((d) => finished.has(d))) continue
      // Iter-8：并发组组级槽位——组内 RUNNING + 该组已列入 result 的数量 >= 组级 max 则不放行
      if (t._concurrentGroup) {
        const gInResult = result.filter((x) => x._concurrentGroup === t._concurrentGroup).length
        if ((gRun.get(t._concurrentGroup) || 0) + gInResult >= (gMax.get(t._concurrentGroup) || 1)) continue
      }
      result.push(t)
    }
    return result
  }

  function setStage(s) {
    state.stage = s
    state.updatedAt = Date.now()
    // Iter-16：STOPPED 也视为无进行中实例（保留 DONE 进度，但编排 Agent 停）
    if (s === E_STAGE.COMPLETED || s === E_STAGE.FAILED || s === E_STAGE.STOPPED) state.active = false
    log('STAGE', s)
  }

  function setGateResult(r) {
    state.gateResult = r
    state.updatedAt = Date.now()
    log('GATE', 'result=' + r)
  }

  function setRetries(n) {
    state.retries = n
    state.updatedAt = Date.now()
  }

  function setError(msg) {
    state.error = msg || null
    state.updatedAt = Date.now()
    if (msg) log('ERROR', msg)
  }

  function setPersist(r) {
    state.persist = r
  }

  // 当 task FAILED 且 _onError === 'break' 时，将同 _loopGroup 的 PENDING 任务标记为 SKIPPED
  function processBreak(taskId) {
    const failed = state.tasks.find((x) => x.id === taskId)
    if (!failed || !failed._loopGroup || failed._onError !== 'break') return false
    let skipped = 0
    state.tasks.forEach((t) => {
      if (t._loopGroup === failed._loopGroup && t.status === E_TASK_STATUS.PENDING && t.id !== taskId) {
        t.status = E_TASK_STATUS.SKIPPED
        t.error = '循环中断：前序迭代 "' + failed.id + '" 失败'
        skipped++
      }
    })
    if (skipped > 0) log('BREAK', '循环 "' + failed._loopGroup + '" 中断，跳过 ' + skipped + ' 个任务')
    return skipped > 0
  }

  function log(action, detail) {
    state.logs.push({ ts: Date.now(), action, detail })
    if (state.logs.length > 500) state.logs.splice(0, state.logs.length - 500)
  }

  function clear() {
    state.workflow = null
    state.version = null
    state.description = null
    state.params = {}
    state.active = false
    state.stage = E_STAGE.PENDING
    state.tasks = []
    state.gateResult = null
    state.retries = 0
    state.error = null
    state.logs = []
    state.updatedAt = Date.now()
  }

  // 从持久化 payload 恢复实例状态（storage.load 调用）
  function hydrate(j) {
    state.workflow = j.workflow
    state.version = j.version
    state.description = j.description
    state.params = j.params || {}
    state.maxConcurrency = j.maxConcurrency || 1 // Iter-7
    state.active = !!j.active
    state.stage = j.stage || E_STAGE.PENDING
    state.gateResult = j.gateResult || null
    state.retries = j.retries || 0
    state.error = j.error || null
    state.updatedAt = Date.now()
    state.logs = Array.isArray(j.logs) ? j.logs.slice(-200) : []
    state.tasks = Array.isArray(j.tasks) ? j.tasks.map((t, i) => ({
      id: t.id,
      name: t.name,
      type: t.type,
      dependsOn: Array.isArray(t.dependsOn) ? t.dependsOn : [],
      status: t.status || E_TASK_STATUS.PENDING,
      processor: t.processor || null,
      outputs: Array.isArray(t.outputs) ? t.outputs : [],
      gate: t.gate || null,
      gateResult: t.gateResult || null,
      retries: t.retries || 0,
      // Iter-6：恢复循环元数据（processBreak 与 Client DAG 分组依赖）
      _loopGroup: t._loopGroup || null,
      _loopItem: t._loopItem || null,
      _loopIndex: t._loopIndex ?? 0,
      _loopGroupName: t._loopGroupName || null,
      _onError: t._onError || null,
      // Iter-8：并发组元数据（engine 组级并发控制 + Client DAG 分组渲染）
      _concurrentGroup: t._concurrentGroup || null,
      _concurrentGroupName: t._concurrentGroupName || null,
      _concurrentItem: t._concurrentItem || null,
      _concurrentIndex: t._concurrentIndex ?? 0,
      _concurrentMax: t._concurrentMax || null,
    })) : []
    state.updatedAt = Date.now()
  }

  // ── Iter-16：运行状态机动作 ───────────────────────────────────────────────
  // 状态：PENDING | RUNNING | STOPPED | COMPLETED | FAILED
  // 转移：start 仅 PENDING（全新 begin→RUNNING）；stop 仅 RUNNING（保进度→STOPPED）；
  //       resume 仅 STOPPED（hydrate 续跑→RUNNING，保 DONE）；reset 仅
  //       STOPPED/COMPLETED/FAILED（丢弃进度→PENDING；RUNNING 须先 stop，PENDING 无内容）。
  function start() {
    if (state.stage !== E_STAGE.PENDING) {
      throw new Error('start 仅允许 PENDING 状态（当前: ' + state.stage + '）；STOPPED/COMPLETED/FAILED 须先 reset')
    }
    state.active = true
    setStage(E_STAGE.RUNNING)
    return snapshot()
  }

  function stop() {
    if (state.stage !== E_STAGE.RUNNING) {
      throw new Error('stop 仅允许 RUNNING 状态（当前: ' + state.stage + '）')
    }
    // Iter-21：STOPPED 时把进行中的 RUNNING 任务重置回 PENDING——否则 resume 后这些任务仍占并发槽且
    // 实际无人执行（其 subagent 已停/终态），导致 runnable=[] 死锁（依赖它们的 PENDING 任务永不可分派）。
    // DONE/SKIPPED/FAILED 保留（终态）；仅"未完成"的 RUNNING 回退。
    state.tasks.forEach((t) => {
      if (t.status === E_TASK_STATUS.RUNNING) t.status = E_TASK_STATUS.PENDING
    })
    setStage(E_STAGE.STOPPED) // setStage 将 active 置 false；保留 DONE 进度
    return snapshot()
  }

  function resume() {
    if (state.stage !== E_STAGE.STOPPED) {
      throw new Error('resume 仅允许 STOPPED 状态（当前: ' + state.stage + '）')
    }
    state.active = true
    setStage(E_STAGE.RUNNING)
    return snapshot()
  }

  function reset() {
    if (state.stage === E_STAGE.PENDING || state.stage === E_STAGE.RUNNING) {
      throw new Error('reset 仅允许 STOPPED/COMPLETED/FAILED 状态（当前: ' + state.stage + '）；RUNNING 须先 stop，PENDING 无执行内容')
    }
    if (!state.def) throw new Error('reset 需要已 begin 的定义')
    begin(state.def) // 丢弃进度，全新 PENDING
    return snapshot()
  }

  // Iter-22：reset 不依赖内存 state.def 的变体。hydrate() 不恢复 def——COMPLETED/STOPPED/FAILED
  // 的历史实例、跨会话/DSH 重启后的 hydrate-only 实例，其 state.def 必为空，reset() 会抛
  // "reset 需要已 begin 的定义"。调用方（workflow_reset 工具 / /wf/reset 路由）从实例
  // instance.yaml 重新解析展开定义后传入；语义与 reset() 相同（仅 STOPPED/COMPLETED/FAILED
  // → 丢弃进度，全新 PENDING）。
  function resetWithDefinition(parsed) {
    if (state.stage === E_STAGE.PENDING || state.stage === E_STAGE.RUNNING) {
      throw new Error('reset 仅允许 STOPPED/COMPLETED/FAILED 状态（当前: ' + state.stage + '）；RUNNING 须先 stop，PENDING 无执行内容')
    }
    if (!parsed) throw new Error('resetWithDefinition 需要解析后的工作流定义')
    begin(parsed) // 丢弃进度，全新 PENDING
    return snapshot()
  }

  return {
    begin,
    clear,
    hydrate,
    updateTask,
    processBreak,
    getRunnableTasks,
    setStage,
    setGateResult,
    setRetries,
    setError,
    setPersist,
    start,
    stop,
    resume,
    reset,
    resetWithDefinition,
    snapshot,
  }
}

// ---- module: storage ----
// ============================================================================
// workflow-agent — 状态持久化
// 文件：code/plugins/workflow-host/storage.js
// 说明：工作流状态落盘/恢复。
//       修正记录（Iter-1 验收发现）：宿主插件没有 session 上下文，
//       sandboxPolicy.workspaceRoot 在宿主侧解析为「部署根」（DSH 安装目录），
//       直接使用会把状态写入安装目录。因此落盘位置不再依赖该 fallback，
//       改由 workflow_begin 调用方显式指定：
//         - setWorkspaceRoot(root)：状态默认写到 <root>/.workflow-agent/state.json
//         - setStatePath(path)    ：完全自定义状态文件路径
//       两者都未设置时 save() 返回错误、load() 返回 false（不抛异常、不写盘）。
// 依赖：ctx（fs）、engine（snapshot/setPersist/hydrate）。
// Iter-10：新增实例目录模式 setInstanceDir(dir)——落点 <dir>/state.json，
//          优先级高于 workspaceRoot 旧布局（<root>/.workflow-agent/state.json）。
// ============================================================================

function createWorkflowStorage(ctx, engine) {
  const sandboxPolicy = ctx.get('sandboxPolicy')

  let workspaceRoot = sandboxPolicy ? (sandboxPolicy.workspaceRoot || '') : ''
  let explicitStatePath = null
  let statePath = null
  let instanceDir = null // Iter-10：实例目录（优先级最高，落点 <instanceDir>/state.json）

  // 由调用方（workflow_begin）在运行时设置，替代宿主 fallback root
  function setWorkspaceRoot(root) {
    workspaceRoot = (root || '').replace(/\\/g, '/').replace(/\/+$/, '')
    statePath = null // 下次访问时重算
  }

  function setStatePath(p) {
    explicitStatePath = p ? String(p).replace(/\\/g, '/') : null
    statePath = null // 下次访问时重算
  }

  // Iter-10：实例目录模式（由 instance-store 的 beginInstance/hydrateLatest 设置）
  function setInstanceDir(dir) {
    instanceDir = dir ? String(dir).replace(/\\/g, '/').replace(/\/+$/, '') : null
    statePath = null
  }

  // 延迟计算状态文件绝对路径（首次读写时解析）
  async function ensurePath() {
    if (statePath) return statePath
    const fs = ctx.get('fs')
    if (!fs) return null
    if (explicitStatePath) {
      statePath = await fs.resolve(explicitStatePath)
      return statePath
    }
    if (instanceDir) {
      statePath = await fs.resolve(instanceDir + '/state.json')
      return statePath
    }
    if (!workspaceRoot) return null
    const dir = (workspaceRoot + '/.workflow-agent').replace(/\/+/g, '/')
    statePath = await fs.resolve(dir + '/state.json')
    return statePath
  }

  // 显式沙箱写策略：写策略根来自实例目录 > workspaceRoot > 状态文件父目录
  function writePolicy() {
    let root = instanceDir || workspaceRoot
    if (!root && explicitStatePath) {
      const idx = explicitStatePath.lastIndexOf('/')
      root = idx > 0 ? explicitStatePath.slice(0, idx) : explicitStatePath
    }
    return {
      mode: 'workspace-write',
      workspaceRoot: root || '',
    }
  }

  async function save() {
    const fs = ctx.get('fs')
    if (!fs) return 'err: no fs'
    try {
      const p = await ensurePath()
      if (!p) return 'err: no workspaceRoot/statePath（请由 workflow_begin 指定）'
      const snap = engine.snapshot()
      const payload = {
        workflow: snap.workflow,
        version: snap.version,
        description: snap.description,
        params: snap.params,
        active: snap.active,
        stage: snap.stage,
        tasks: snap.tasks,
        gateResult: snap.gateResult,
        retries: snap.retries,
        error: snap.error,
        updatedAt: snap.updatedAt,
        logs: snap.logs,
      }
      await fs.writeText(p, JSON.stringify(payload, null, 2), undefined, undefined, writePolicy())
      const r = 'ok'
      engine.setPersist(r)
      return r
    } catch (e) {
      const r = 'err: ' + ((e && e.message) || String(e))
      engine.setPersist(r)
      return r
    }
  }

  // 恢复：仅当存在有效状态文件时执行
  async function load() {
    const fs = ctx.get('fs')
    if (!fs) return false
    try {
      const p = await ensurePath()
      if (!p) return false
      const text = await fs.readText(p)
      const j = JSON.parse(text)
      if (!j || !j.workflow) return false
      engine.hydrate(j)
      return true
    } catch (e) {
      return false // 无之前状态
    }
  }

  return { save, load, setWorkspaceRoot, setStatePath, setInstanceDir }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { createWorkflowStorage }
}


// ---- module: instance-store ----
// ============================================================================
// workflow-agent — 实例注册表与目录布局（Iter-10 多实例存储）
// 文件：code/plugins/workflow-host/instance-store.js
// 说明：多实例的核心数据结构与目录约定。
//       目录布局（锚点 = session cwd；DSH 沙箱按 session 解析，"A session cwd
//       is its workspace-write boundary"，实例目录建在会话工作区内即拥有完全
//       本地读写权限；Iter-9 探针证实 fs 嵌套写/读回可用）：
//         <cwd>/.workflow-agent/instances/<instanceId>/
//           ├── instance.yaml   # 实例定义快照（源 YAML + 参数注释头，源定义只读）
//           ├── state.json      # engine snapshot（storage.setInstanceDir 落点）
//           ├── metadata.json   # { instanceId, workflowName, sessionId, ... }
//           ├── output/         # 每实例产物
//           └── logs/           # 每实例日志
//       实例 id = slug(workflowName) + '-' + uuid8（设计文档定稿；
//       Iter-9 证实 session id 唯一 guard，uuid8 天然防撞）。
//       metadata.json 是 instanceId↔sessionId 的主映射（重启后惰性 hydrate 依据：
//       session id 跨重启稳定，按 sessionId 精确匹配优先、createdAt 最新兜底）。
// 依赖：ctx（fs）；engine/storage 工厂由 deps 注入（便于 Node 单测）。
// ============================================================================

// ── 工作流名 → 实例 id 前缀（安全文件名片段）────────────────────────────────
function slugifyName(name) {
  const s = String(name || '').toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '')
  return s || 'wf'
}

// ── 8 位十六进制唯一后缀（时间尾 + 随机，实例级足够；目录重名由唯一性兜底）──
function makeUuid8() {
  return (Date.now().toString(16).slice(-4) + Math.random().toString(16).slice(2, 6)).slice(0, 8)
}

// ── 路径计算 ────────────────────────────────────────────────────────────────
function normalizeDir(p) {
  return String(p || '').replace(/\\/g, '/').replace(/\/+$/, '')
}

function instancesRootPath(cwd) {
  return (normalizeDir(cwd) + '/.workflow-agent/instances').replace(/\/+/g, '/')
}

function instanceDirPath(cwd, instanceId) {
  return instancesRootPath(cwd) + '/' + instanceId
}

// Iter-17：归档库路径（<cwd>/.workflow-agent/archive；移出池只读，Iter-19 起使用）
function archiveRootPath(cwd) {
  return (normalizeDir(cwd) + '/.workflow-agent/archive').replace(/\/+/g, '/')
}

// Iter-18：归档目录时间戳（YYYYMMDDTHHMMSSZ，与 lifecycle-design §7 一致）
function archiveTimestamp() {
  return new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+/, '')
}

// ── Iter-23(方向A)：用户手工停判定（A1 事件 tap / A2 轮询兜底共用纯函数）──────
// 探针实证（iter23-probe-report.md）：手工停活动回合在 session log 留
// turn/end data={turn,reason:{kind:'aborted',reason:{kind:'user'|...}}}（部署版 payload 在
// data 包装下）。非用户原因（parent=级联 interrupt / hook / disposed / legacy / completed /
// 无 reason / 非 turn-end / 畸形事件）一律不判 user-stop。
function isUserAbortTurnEnd(event) {
  try {
    if (!event || event.type !== 'turn/end') return false
    const d = event.data && typeof event.data === 'object' ? event.data : {}
    const reason = d.reason
    if (!reason || typeof reason !== 'object' || reason.kind !== 'aborted') return false
    return !!(reason.reason && typeof reason.reason === 'object' && reason.reason.kind === 'user')
  } catch (e) {
    return false
  }
}

// 会话日志末条回合终局是否为"用户中止"（A2 轮询兜底判定）。只看末条 turn/end：
// 末条被更新的回合（如结算通知唤醒后跑完）覆盖时返回 false——该窄窗口由 A1 事件驱动
// 即时处置覆盖。日志不可读/为空返回 undefined（调用方降级为既有 session-idle 语义）。
function detectUserAbortFromLog(log) {
  try {
    if (!log || typeof log.length !== 'number' || log.length === 0) return undefined
    for (let i = log.length - 1; i >= 0; i--) {
      const ev = log[i]
      if (!ev || ev.type !== 'turn/end') continue
      return isUserAbortTurnEnd(ev)
    }
    return false // 无任何回合终局（空会话）
  } catch (e) {
    return undefined
  }
}

// ── metadata.json 组装（lossless JSON；sessionId 缺省 null 而非 undefined）──
function composeMetadata(m) {
  return {
    instanceId: m.instanceId,
    workflowName: m.workflowName,
    sessionId: m.sessionId === undefined ? null : m.sessionId,
    sessionCwd: m.sessionCwd || null,
    sourcePath: m.sourcePath || null,
    params: m.params && typeof m.params === 'object' ? m.params : {},
    createdAt: m.createdAt || new Date().toISOString(),
  }
}

// ── 实例注册表：instanceId → {engine, storage, meta}；sessionId → 活跃实例 ──
function createInstanceRegistry(ctx, deps) {
  const engines = new Map()        // instanceId -> entry
  const activeBySession = new Map() // sessionId -> instanceId
  // Iter-18：会话存活判定（孤儿识别依赖）。生产由 apply 注入 sessions 服务包装，
  // 测试注入可控 stub；缺省恒 true（不误判孤儿，保持既有行为）。
  const isSessionLive = typeof deps.isSessionLive === 'function' ? deps.isSessionLive : (() => true)
  // Iter-19：会话 agent 是否运行中（Session 启停同步依赖）。生产由 apply 注入 agents 服务包装；
  // 缺省返回 undefined（无法判定 → 不触发同步，保持既有行为）。
  const isAgentRunning = typeof deps.isAgentRunning === 'function' ? deps.isAgentRunning : (() => undefined)
  // Iter-22(S1)：排队用户输入判定（idle→stop 守卫依赖）。生产由 apply 注入 agents 服务包装
  // （agents.get(sid).inbox.hasPending）；缺省恒 false（无信号不阻止 stop，保持既有行为）。
  // 探针结论（Iter-22 S1 探针）：提问等待（ask_user_question 阻塞）期间 status 仍为 running，
  // 不产生 idle；hasPending=true 仅出现在用户消息已排队、driver 尚未认领的间隙——该间隙不得误停。
  const isAgentPending = typeof deps.isAgentPending === 'function' ? deps.isAgentPending : (() => false)
  // Iter-SUBA(P1/P3)：会话树子会话聚合探针。生产由 apply 注入 apiProxy.subagents 包装：
  //   listRunningChildren(sid) → 仍在上跑（activity==='running'）的子会话 id 数组（含历史枚举，
  //   activity 由 apiProxy 用 agents.get(id)?.status==='running' 重算——官方同款判活）
  //   interruptChild(sid, childId) → 级联打断子会话当前回合（fire-and-return；one-shot/absent=no-op）
  // 缺省 no-op（无子会话信息 → 不守卫直接停，保持既有行为）。
  const listRunningChildren = typeof deps.listRunningChildren === 'function' ? deps.listRunningChildren : (async () => [])
  const interruptChild = typeof deps.interruptChild === 'function' ? deps.interruptChild : (async () => {})
  // Iter-23(A2)：会话日志末条回合终局"用户中止"探针。生产由 apply 注入（agents.get(sid).session.log
  // → detectUserAbortFromLog 纯函数）；缺省恒 undefined（无法判定 → 降级为 session-idle 既有语义）。
  const detectUserAbort = typeof deps.detectUserAbort === 'function' ? deps.detectUserAbort : (async () => undefined)

  function get(instanceId) {
    return engines.get(instanceId)
  }

  function activeIdFor(sessionId) {
    return activeBySession.get(sessionId)
  }

  // 工具执行上下文 → sessionId（与 tools-preset 的 sessionCwd 同构）
  function sessionIdOf(exec) {
    try {
      const id = exec && exec.agent && exec.agent.session && exec.agent.session.header && exec.agent.session.header.id
      return typeof id === 'string' && id.length > 0 ? id : undefined
    } catch (e) {
      return undefined
    }
  }

  // ── 创建实例目录 + 引擎条目（workflow_begin 成功路径调用）────────────────
  async function beginInstance(opts) {
    const fs = ctx.get('fs')
    if (!fs) throw new Error('fs service unavailable')
    const cwd = normalizeDir(opts.cwd)
    if (!cwd) throw new Error('session cwd 未提供，无法创建实例目录')
    await ensureWorkspaceSkeleton(cwd) // Iter-17：首次挂接物化骨架（instances/ + archive/）
    const workflowName = opts.workflowName || 'wf'
    const instanceId = slugifyName(workflowName) + '-' + makeUuid8()
    const dir = instanceDirPath(cwd, instanceId)
    const meta = composeMetadata({
      instanceId,
      workflowName,
      sessionId: opts.sessionId,
      sessionCwd: cwd,
      sourcePath: opts.sourcePath,
      params: opts.params,
    })
    // 目录 + 固定文件（fs.writeText 自动建父目录；Iter-9 探针 P7 已验证嵌套写）
    await fs.writeText(await fs.resolve(dir + '/metadata.json'), JSON.stringify(meta, null, 2))
    const header = [
      '# workflow 实例定义快照（参数化副本；源定义文件保持只读）',
      '# source: ' + (opts.sourcePath || '(inline workflowText)'),
      '# instanceId: ' + instanceId,
      '# createdAt: ' + meta.createdAt,
      '# params: ' + JSON.stringify(opts.params || {}),
      '',
    ].join('\n')
    await fs.writeText(await fs.resolve(dir + '/instance.yaml'), header + String(opts.sourceText || ''))
    await fs.writeText(await fs.resolve(dir + '/output/.gitkeep'), '')
    await fs.writeText(await fs.resolve(dir + '/logs/.gitkeep'), '')
    // 引擎 + 存储（engine 零改造；存储落点 = 实例目录 state.json）
    const engine = deps.createWorkflowEngine()
    const storage = deps.createWorkflowStorage(ctx, engine)
    storage.setInstanceDir(dir)
    const entry = { instanceId, dir, meta, engine, storage, hasState: false }
    engines.set(instanceId, entry)
    if (opts.sessionId) activeBySession.set(opts.sessionId, instanceId)
    return entry
  }

  // 工具执行上下文 → 会话 cwd（Iter-11：操控工具的实例定位锚点）
  function sessionCwdOf(exec) {
    try {
      const c = exec && exec.agent && exec.agent.session && exec.agent.session.header && exec.agent.session.header.cwd
      return typeof c === 'string' && c ? c : undefined
    } catch (e) {
      return undefined
    }
  }

  // ── 会话当前活跃实例；未命中则按实例目录惰性恢复（DSH 重启后首次调用）────
  async function forSession(exec) {
    const sessionId = sessionIdOf(exec)
    const hit = sessionId ? activeBySession.get(sessionId) : undefined
    if (hit && engines.get(hit)) {
      await syncInstanceState(sessionCwdOf(exec), hit) // Iter-19：Session 启停同步
      return engines.get(hit)
    }
    const cwd = sessionCwdOf(exec)
    if (!cwd) return undefined
    const restored = await hydrateLatest(cwd, sessionId)
    if (!restored) return undefined
    if (sessionId) activeBySession.set(sessionId, restored.instanceId)
    await syncInstanceState(cwd, restored.instanceId) // Iter-19：Session 启停同步
    return restored
  }

  // ── 扫描实例目录恢复最新实例（metadata.sessionId 精确匹配优先）────────────
  async function hydrateLatest(cwd, sessionId) {
    const fs = ctx.get('fs')
    if (!fs) return undefined
    let dirs = []
    try {
      const entries = await fs.listDir(await fs.resolve(instancesRootPath(cwd)))
      dirs = entries.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) {
      return undefined // 无 instances 目录（该 cwd 从未运行过实例）
    }
    const candidates = []
    for (const id of dirs) {
      try {
        const meta = JSON.parse(await fs.readText(await fs.resolve(instanceDirPath(cwd, id) + '/metadata.json')))
        if (!meta || meta.instanceId !== id) continue
        const state = JSON.parse(await fs.readText(await fs.resolve(instanceDirPath(cwd, id) + '/state.json')))
        if (!state || !state.workflow) continue
        candidates.push({ meta, state })
      } catch (e) { /* 残缺实例目录跳过 */ }
    }
    if (candidates.length === 0) return undefined
    // Iter-20：只返回声明了该 sessionId 的实例；会话未绑定（UNBOUND）→ undefined。
    // 绝不回退取"工作区最新实例"（那可能是别的会话的，导致归属污染/空态误显示 DAG/Start 注入错实例）。
    const matched = sessionId ? candidates.find(c => c.meta.sessionId === sessionId) : null
    if (!matched) return undefined
    const best = matched
    const dir = instanceDirPath(cwd, best.meta.instanceId)
    const engine = deps.createWorkflowEngine()
    const storage = deps.createWorkflowStorage(ctx, engine)
    storage.setInstanceDir(dir)
    engine.hydrate(best.state)
    const entry = { instanceId: best.meta.instanceId, dir, meta: best.meta, engine, storage }
    engines.set(entry.instanceId, entry)
    return entry
  }

  // ── Iter-11：精确加载实例为条目（有 state.json 则 hydrate；无则为空白引擎）──
  // 返回 entry 或 undefined（目录/metadata 不存在）。opts.active=true 时标记为
  // 当前会话活跃实例。
  async function loadEntry(cwd, instanceId, opts) {
    const fs = ctx.get('fs')
    if (!fs || !instanceId) return undefined
    const dir = instanceDirPath(cwd, instanceId)
    let meta
    try {
      meta = JSON.parse(await fs.readText(await fs.resolve(dir + '/metadata.json')))
    } catch (e) {
      return undefined // 目录或 metadata 不存在
    }
    if (!meta || meta.instanceId !== instanceId) return undefined
    const existing = engines.get(instanceId)
    if (existing) {
      if (opts && opts.active) {
        const sid = opts.sessionId || meta.sessionId
        if (sid) activeBySession.set(sid, instanceId)
      }
      return existing
    }
    const engine = deps.createWorkflowEngine()
    const storage = deps.createWorkflowStorage(ctx, engine)
    storage.setInstanceDir(dir)
    let hasState = false
    try {
      const state = JSON.parse(await fs.readText(await fs.resolve(dir + '/state.json')))
      if (state && state.workflow) {
        engine.hydrate(state)
        hasState = true
      }
    } catch (e) { /* 无 state.json → CREATED 阶段的空白条目 */ }
    const entry = { instanceId, dir, meta, engine, storage, hasState }
    engines.set(instanceId, entry)
    if (opts && opts.active) {
      const sid = opts.sessionId || meta.sessionId
      if (sid) activeBySession.set(sid, instanceId)
    }
    return entry
  }

  // ── Iter-11：操控工具的实例解析（显式 instanceId 优先，缺省走会话活跃）────
  async function resolveEntry(exec, instanceId, opts) {
    const cwd = sessionCwdOf(exec)
    if (instanceId) {
      if (!cwd) return undefined
      return loadEntry(cwd, instanceId, opts)
    }
    return forSession(exec)
  }

  // ── Iter-11：列出当前 cwd 下全部实例（metadata + state 摘要，createdAt 倒序）──
  // phase: 'CREATED'（仅目录，未启动过）| 'READY'（有 state.json）
  // ── Iter-20：轻量会话绑定态（BOUND/UNBOUND/BROKEN）──────────────
  // 供 /wf/list 等轮询路径 gating 用：只扫描 metadata.sessionId，不物化骨架、不整树扫描。
  // （session 状态按设计是派生的，无存储字段；这里给一个轻量判定。）
  async function sessionBindState(cwd, sessionId) {
    if (!sessionId) return { state: 'UNBOUND' }
    const fs = ctx.get('fs')
    if (!fs) return { state: 'UNBOUND' }
    let dirs = []
    try {
      const ins = await fs.listDir(await fs.resolve(instancesRootPath(cwd)))
      dirs = ins.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) { return { state: 'UNBOUND' } }
    let bound = null
    for (const id of dirs) {
      const meta = await tryReadMeta(cwd, id)
      if (meta && meta.sessionId === sessionId) {
        if (bound) return { state: 'BROKEN', reason: 'CONFLICT: 会话被多实例占用/' + sessionId }
        bound = { id, meta }
      }
    }
    if (bound) return { state: 'BOUND', instanceId: bound.id }
    return { state: 'UNBOUND' }
  }

  async function listInstances(cwd) {
    const fs = ctx.get('fs')
    if (!fs) return []
    let dirs = []
    try {
      const entries = await fs.listDir(await fs.resolve(instancesRootPath(cwd)))
      dirs = entries.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) {
      return [] // 无 instances 目录
    }
    const out = []
    for (const id of dirs) {
      try {
        const meta = JSON.parse(await fs.readText(await fs.resolve(instanceDirPath(cwd, id) + '/metadata.json')))
        if (!meta || meta.instanceId !== id) continue
        const item = {
          instanceId: id,
          workflowName: meta.workflowName,
          sessionId: meta.sessionId || null,
          createdAt: meta.createdAt || null,
          lastResetAt: meta.lastResetAt || null,
          phase: 'CREATED',
          stage: null,
          active: !!meta.sessionId && activeBySession.get(meta.sessionId) === id,
          taskTotal: 0,
          taskDone: 0,
          taskFailed: 0,
        }
        // Iter-20(R4)：绑定实例先做 Session 启停同步（idle→stop / running→resume），列表不再见过期 RUNNING
        const entry = meta.sessionId ? await syncInstanceState(cwd, id) : undefined
        if (entry && entry.hasState) {
          const snap = entry.engine.snapshot()
          item.phase = 'READY'
          item.stage = snap.stage
          item.taskTotal = snap.tasks.length
          item.taskDone = snap.tasks.filter(t => t.status === 'DONE').length
          item.taskFailed = snap.tasks.filter(t => t.status === 'FAILED').length
        } else {
          try {
            const state = JSON.parse(await fs.readText(await fs.resolve(instanceDirPath(cwd, id) + '/state.json')))
            if (state && state.workflow) {
              item.phase = 'READY'
              item.stage = state.stage || null
              const tasks = Array.isArray(state.tasks) ? state.tasks : []
              item.taskTotal = tasks.length
              item.taskDone = tasks.filter(t => t.status === 'DONE').length
              item.taskFailed = tasks.filter(t => t.status === 'FAILED').length
            }
          } catch (e) { /* 无 state.json → CREATED */ }
        }
        // Iter-22(D4 修复)：池内（sessionId==null）不应存在 RUNNING——历史 recoverOrphan 未落盘
        // 的残留，或异常路径产物。发现即从磁盘状态水合全新引擎补 stop+落盘（幂等自愈），
        // 并同步既有内存条目，避免采用池出现误导性 RUNNING。
        if (!meta.sessionId && item.phase === 'READY' && item.stage === 'RUNNING') {
          try {
            const state = JSON.parse(await fs.readText(await fs.resolve(instanceDirPath(cwd, id) + '/state.json')))
            if (state && state.workflow) {
              const nEngine = deps.createWorkflowEngine()
              nEngine.hydrate(state)
              nEngine.stop()
              const nStorage = deps.createWorkflowStorage(ctx, nEngine)
              nStorage.setInstanceDir(instanceDirPath(cwd, id))
              const nr = await nStorage.save()
              const memEntry = engines.get(id)
              if (memEntry && memEntry.hasState) {
                memEntry.engine.hydrate(nr)
                memEntry.engine.setPersist(nr)
              }
              item.stage = 'STOPPED'
            }
          } catch (e) { /* 自愈失败降级为原状态标注，不阻塞列表 */ }
        }
        out.push(item)
      } catch (e) { /* 残缺实例目录跳过 */ }
    }
    out.sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))
    return out
  }

  // ── Iter-11：更新实例 metadata 的辅助字段（如 reset 的 lastResetAt）────────
  async function patchMeta(cwd, instanceId, patch) {
    const fs = ctx.get('fs')
    if (!fs) return undefined
    const p = instanceDirPath(cwd, instanceId) + '/metadata.json'
    try {
      const meta = JSON.parse(await fs.readText(await fs.resolve(p)))
      if (!meta || meta.instanceId !== instanceId) return undefined
      const next = Object.assign({}, meta, patch || {})
      await fs.writeText(await fs.resolve(p), JSON.stringify(next, null, 2))
      const entry = engines.get(instanceId)
      if (entry) entry.meta = next
      return next
    } catch (e) {
      return undefined
    }
  }

  // ── Iter-17：工作区骨架物化（instances/ + archive/）────────────────────────
  // 首次挂接 workflow 会话时调用；幂等。落 .gitkeep 标记，mock/真实 fs 均物化目录
  // （fs.writeText 自动建父目录）。骨架在场是完整性判定（checkWorkspaceTreeIntegrity）
  // 的前置，但物化本身不判定缺场（缺场=删除后异常，由完整性检查单独识别根异常）。
  async function ensureWorkspaceSkeleton(cwd) {
    const fs = ctx.get('fs')
    if (!fs) throw new Error('fs service unavailable')
    const root = (normalizeDir(cwd) + '/.workflow-agent').replace(/\/+/g, '/')
    await fs.writeText(await fs.resolve(root + '/instances/.gitkeep'), '')
    await fs.writeText(await fs.resolve(root + '/archive/.gitkeep'), '')
    return root
  }

  // 读取某实例的有效 metadata（能解析且 instanceId 匹配目录名；否则视为损坏）
  async function tryReadMeta(cwd, instanceId) {
    const fs = ctx.get('fs')
    const p = instanceDirPath(cwd, instanceId) + '/metadata.json'
    try {
      const meta = JSON.parse(await fs.readText(await fs.resolve(p)))
      if (!meta || meta.instanceId !== instanceId) return null
      return meta
    } catch (e) {
      return null
    }
  }

  // 扫描 archive/<instanceId>/<ts>_<kind>_<state>/metadata.json 是否含绑定 sessionId
  // （Iter-19 起产生归档；DONE 派生依赖。当前无归档时恒 false）。
  async function archiveDeclaresSession(cwd, sessionId) {
    const fs = ctx.get('fs')
    let instanceDirs = []
    try {
      const ar = await fs.listDir(await fs.resolve(archiveRootPath(cwd)))
      instanceDirs = ar.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) {
      return false // 无 archive
    }
    for (const iid of instanceDirs) {
      let subDirs = []
      try {
        const subs = await fs.listDir(await fs.resolve(archiveRootPath(cwd) + '/' + iid))
        subDirs = subs.filter(en => en.type === 'directory').map(en => en.name)
      } catch (e) { continue }
      for (const sub of subDirs) {
        try {
          const m = JSON.parse(await fs.readText(await fs.resolve(archiveRootPath(cwd) + '/' + iid + '/' + sub + '/metadata.json')))
          if (m && m.sessionId === sessionId) return true
        } catch (e) { /* skip */ }
      }
    }
    return false
  }

  // ── Iter-17：整树完整性判定（纯完整性，不设独立绑定指针）────────────────
  // 判定标准 = .workflow-agent 整树：在场且自洽 → ok；骨架缺场 / 退化（实例目录
  // 损坏）/ 冲突（1:1 违反）→ not ok。返回 {ok, reason?, instances, archives}。
  async function checkWorkspaceTreeIntegrity(cwd) {
    const fs = ctx.get('fs')
    if (!fs) return { ok: false, reason: 'fs-unavailable' }
    const agentRoot = (normalizeDir(cwd) + '/.workflow-agent').replace(/\/+/g, '/')
    let children = []
    try {
      children = await fs.listDir(await fs.resolve(agentRoot))
    } catch (e) {
      // 未物化（更从未运行过）→ 空，非 BROKEN（首挂接由 ensureWorkspaceSkeleton 物化）
      return { ok: true, instances: [], archives: [] }
    }
    const dirs = children.filter(c => c.type === 'directory').map(c => c.name)
    // 骨架在场校验：agentRoot 有内容时必须含 instances/（archive/ 由物化补齐）
    if (children.length > 0 && !dirs.includes('instances')) {
      return { ok: false, reason: 'SKELETON_MISSING: 骨架缺场（缺 instances/）' }
    }
    let instanceDirs = []
    try {
      const ins = await fs.listDir(await fs.resolve(instancesRootPath(cwd)))
      instanceDirs = ins.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) {
      instanceDirs = []
    }
    const seenSession = new Map() // sessionId -> instanceId
    const instances = []
    for (const id of instanceDirs) {
      const meta = await tryReadMeta(cwd, id)
      if (!meta) return { ok: false, reason: 'CORRUPT: 实例目录损坏/' + id }
      instances.push({ id, meta })
      if (meta.sessionId) {
        if (seenSession.has(meta.sessionId)) {
          return { ok: false, reason: 'CONFLICT: 会话被多实例占用/' + meta.sessionId }
        }
        seenSession.set(meta.sessionId, id)
      }
    }
    let archives = []
    try {
      const ar = await fs.listDir(await fs.resolve(archiveRootPath(cwd)))
      archives = ar.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) { archives = [] }
    return { ok: true, instances, archives }
  }

  // ── Iter-17：派生会话状态（UNBOUND/BOUND/DONE/BROKEN）─────────────────────
  // 权威在实例侧；会话状态不定存，实时从实例+整树派生，不侵入 DSH Session。
  // BOUND=恰好一个结构完好实例声明 S；DONE=archive 声明 S；UNBOUND=无声明；
  // BROKEN=整树损坏/冲突。
  async function deriveSessionState(cwd, sessionId) {
    await ensureWorkspaceSkeleton(cwd)
    const integ = await checkWorkspaceTreeIntegrity(cwd)
    if (!integ.ok) return { state: 'BROKEN', reason: integ.reason }
    const bound = integ.instances.filter(x => x.meta.sessionId === sessionId)
    if (bound.length === 1) return { state: 'BOUND', instanceId: bound[0].id }
    if (bound.length > 1) return { state: 'BROKEN', reason: 'CONFLICT: 会话被多实例占用/' + sessionId }
    if (await archiveDeclaresSession(cwd, sessionId)) return { state: 'DONE' }
    return { state: 'UNBOUND' }
  }

  // ── Iter-19：解绑冲突实例（数据自愈，明确告知用户）────────────────────────
  // CONFLICT（同 sessionId 被多实例声明）不该让整工作区永久 BROKEN。
  // 策略：不自动"保留最新"（可能非当前会话实例），而是在用户新建实例时，把
  // 所有涉及冲突绑定的实例解绑（sessionId→null 回 UNBOUND 池），新建实例绑定
  // 当前会话；调用方须把 unbound 列表明确告知用户。
  async function recoverBindingConflicts(cwd) {
    const fs = ctx.get('fs')
    if (!fs) return { unbound: [], conflicts: [] }
    let dirs = []
    try {
      const ins = await fs.listDir(await fs.resolve(instancesRootPath(cwd)))
      dirs = ins.filter(en => en.type === 'directory').map(en => en.name)
    } catch (e) { return { unbound: [], conflicts: [] } }
    const metas = []
    for (const id of dirs) {
      const meta = await tryReadMeta(cwd, id)
      if (meta && meta.sessionId) metas.push({ id, meta })
    }
    const cnt = new Map()
    for (const { meta } of metas) cnt.set(meta.sessionId, (cnt.get(meta.sessionId) || 0) + 1)
    const conflicted = new Set([...cnt].filter(([s, c]) => c > 1).map(([s]) => s))
    const unbound = []
    for (const { id, meta } of metas) {
      if (conflicted.has(meta.sessionId)) {
        await patchMeta(cwd, id, { sessionId: null })
        activeBySession.delete(meta.sessionId)
        unbound.push(id)
      }
    }
    return { unbound, conflicts: [...conflicted] }
  }

  // ── Iter-17：create-bind（UNBOUND→BOUND，新建实例并写 metadata.sessionId=S）──
  async function createBind(cwd, sessionId, opts) {
    if (!sessionId) throw new Error('createBind 需要 sessionId')
    await ensureWorkspaceSkeleton(cwd)
    let integ = await checkWorkspaceTreeIntegrity(cwd)
    let recovered = []
    // Iter-19：CONFLICT 自愈——不解绑"最新"，而是把冲突的旧实例解绑回池，再新建当前绑定
    if (!integ.ok && /^CONFLICT/.test(integ.reason || '')) {
      const rec = await recoverBindingConflicts(cwd)
      recovered = rec.unbound
      integ = await checkWorkspaceTreeIntegrity(cwd)
    }
    if (!integ.ok) throw new Error('工作区完整性异常，无法绑定: ' + integ.reason)
    if (integ.instances.some(x => x.meta.sessionId === sessionId)) {
      throw new Error('会话 ' + sessionId + ' 已绑定实例（1:1 守卫，禁再绑）')
    }
    const entry = await beginInstance(Object.assign({}, opts, { cwd, sessionId }))
    entry._recoveredConflict = recovered // 供 route/tool 明确告知用户
    return entry
  }

  // ── Iter-17：adopt（UNBOUND→BOUND，采用池中 sessionId==null 实例并写 S）──
  async function adoptInstance(cwd, sessionId, instanceId) {
    const fs = ctx.get('fs')
    if (!fs) throw new Error('fs service unavailable')
    if (!sessionId) throw new Error('adopt 需要 sessionId')
    await ensureWorkspaceSkeleton(cwd)
    const integ = await checkWorkspaceTreeIntegrity(cwd)
    if (!integ.ok) throw new Error('工作区完整性异常，无法采用: ' + integ.reason)
    if (integ.instances.some(x => x.meta.sessionId === sessionId)) {
      throw new Error('会话 ' + sessionId + ' 已绑定实例（1:1 守卫，禁再绑）')
    }
    const target = integ.instances.find(x => x.id === instanceId)
    if (!target) throw new Error('实例不存在: ' + instanceId)
    if (target.meta.sessionId) {
      throw new Error('实例 ' + instanceId + ' 已被会话占用（sessionId=' + target.meta.sessionId + '），不可采用')
    }
    // 运行态守卫：RUNNING 实例须先 stop 再采用（避免两会话驱动同一 RUNNING 实例）
    let stage = null
    try {
      const st = JSON.parse(await fs.readText(await fs.resolve(instanceDirPath(cwd, instanceId) + '/state.json')))
      if (st && st.workflow) stage = st.stage || null
    } catch (e) { /* 无 state */ }
    if (stage === 'RUNNING') throw new Error('实例 ' + instanceId + ' 运行中，先 stop 再采用')
    await patchMeta(cwd, instanceId, { sessionId })
    activeBySession.set(sessionId, instanceId)
    return loadEntry(cwd, instanceId, { active: true })
  }

  // ── Iter-18：孤儿识别（绑定会话离开 live store 的实例）────────────────────
  // 判定 = !isSessionLive(boundSessionId)；归档≠死亡（归档仅改 UI，会话仍 live）。
  async function scanOrphans(cwd) {
    const integ = await checkWorkspaceTreeIntegrity(cwd)
    if (!integ.ok) return []
    const orphans = []
    for (const inst of integ.instances) {
      const sid = inst.meta.sessionId
      if (sid && !isSessionLive(sid)) orphans.push({ id: inst.id, sessionId: sid })
    }
    return orphans
  }

  // ── Iter-18：孤儿回收（RUNNING 先 stop → 解绑→保留 state.json 回 UNBOUND 池）──
  async function recoverOrphan(cwd, instanceId) {
    const entry = await loadEntry(cwd, instanceId)
    if (!entry) throw new Error('实例不存在: ' + instanceId)
    const sid = entry.meta.sessionId
    if (!sid) throw new Error('实例 ' + instanceId + ' 无绑定，非孤儿')
    if (isSessionLive(sid)) throw new Error('实例 ' + instanceId + ' 绑定会话仍存活，非孤儿')
    // Iter-22(D4 修复)：以磁盘 state.json 为准（缓存 entry 可能 hasState=false 或陈旧）。
    // RUNNING 孤儿先 stop 并落盘——否则 state.json 残留 RUNNING 进采用池 → 被误标"未启动"。
    try {
      const fsSvc = ctx.get('fs')
      const state = JSON.parse(await fsSvc.readText(await fsSvc.resolve(entry.dir + '/state.json')))
      if (state && state.workflow) {
        if (!entry.hasState) { entry.engine.hydrate(state); entry.hasState = true }
        if (entry.engine.snapshot().stage === 'RUNNING') {
          entry.engine.stop()
          const r = await entry.storage.save()
          entry.engine.setPersist(r)
        }
      }
    } catch (e) { /* 无 state.json（CREATED 孤儿）→ 跳过 stop */ }
    await patchMeta(cwd, instanceId, { sessionId: null })
    activeBySession.delete(sid)
    return loadEntry(cwd, instanceId)
  }

  // ── Iter-18：写归档备份（reset 用 kind=reset；显式归档用 kind=archive，Iter-19）──
  // 复制实例内容到 archive/<instanceId>/<ts>_<kind>_<state>/ + manifest.json。
  async function writeArchiveBackup(cwd, instanceId, kind, state) {
    const fs = ctx.get('fs')
    if (!fs) throw new Error('fs service unavailable')
    const ts = archiveTimestamp()
    const dest = archiveRootPath(cwd) + '/' + instanceId + '/' + ts + '_' + kind + '_' + state
    const src = instanceDirPath(cwd, instanceId)
    for (const f of ['metadata.json', 'instance.yaml', 'state.json']) {
      try {
        const text = await fs.readText(await fs.resolve(src + '/' + f))
        await fs.writeText(await fs.resolve(dest + '/' + f), text)
      } catch (e) { /* 实例可能无该文件（如 CREATED 无 state.json） */ }
    }
    for (const sub of ['output', 'logs']) {
      try {
        const entries = await fs.listDir(await fs.resolve(src + '/' + sub))
        for (const en of entries) {
          if (en.type !== 'file') continue
          try {
            const text = await fs.readText(await fs.resolve(src + '/' + sub + '/' + en.name))
            await fs.writeText(await fs.resolve(dest + '/' + sub + '/' + en.name), text)
          } catch (e) { /* skip */ }
        }
      } catch (e) { /* skip */ }
    }
    const meta = await tryReadMeta(cwd, instanceId)
    const manifest = {
      kind,
      state,
      reason: kind === 'reset' ? 'reset_backup' : 'archive',
      archivedAt: new Date().toISOString(),
      workflowName: meta ? meta.workflowName : null,
    }
    await fs.writeText(await fs.resolve(dest + '/manifest.json'), JSON.stringify(manifest, null, 2))
    return dest
  }

  // ── Iter-23(方向A)：权威 user-stop 处置（A1 事件驱动与 A2 轮询兜底共用）──────
  // 语义与 workflow_stop 工具一致：STOPPED（保 DONE）+ 落盘 + stopReason='user-stop'
  // + 级联 interrupt running 子会话（用户停止权威性高于 P1 子在跑守卫）。级联失败不阻断。
  async function applyUserStop(entry, cwd) {
    entry.engine.stop() // RUNNING→STOPPED，保 DONE 进度
    await entry.storage.save()
    entry.engine.setPersist('ok (user-stop)')
    if (cwd) await patchMeta(cwd, entry.instanceId, { stopReason: 'user-stop' })
    let stoppedChildren = 0
    try {
      const sid = entry.meta.sessionId
      const childIds = sid ? await listRunningChildren(sid) : []
      for (const cid of childIds) {
        try { await interruptChild(sid, cid); stoppedChildren += 1 } catch (e) { /* 单子失败不阻断 */ }
      }
    } catch (e) { /* 探针故障：级联降级为不打断（不阻断权威停止本身） */ }
    return { instanceId: entry.instanceId, stoppedChildren }
  }

  // Iter-23(A1)：事件驱动入口——mjs 的 session/event tap 检出绑定会话回合 aborted(user) 后调用。
  // 仅处置"绑定且 RUNNING"实例（幂等：非 RUNNING/未绑定直接跳过）；引擎条目缺失（重启后未
  // hydrate）时返回 null，由 A2 轮询兜底在首次 sync 时处置。
  async function handleSessionUserStop(sessionId) {
    const instanceId = sessionId ? activeBySession.get(sessionId) : undefined
    if (!instanceId) return null
    const entry = engines.get(instanceId)
    if (!entry) return null
    let stage = null
    try { stage = entry.engine.snapshot().stage } catch (e) { stage = null }
    if (stage !== 'RUNNING') return null
    const cwd = entry.meta.sessionCwd || null
    return applyUserStop(entry, cwd)
  }

  // ── Iter-19：Session 启停同步（前后台状态配合）────────────────────────────
  // Iter-22(S1)：idle→stop + 排队输入守卫；running→resume 自动恢复移除（wf 只能显式 workflow_resume）。
  // Iter-SUBA(P1/P2) 修订——会话树聚合三态语义（用户拍板）：
  //   主 idle + 有 running 子会话 → 不 stop（wf 保持 RUNNING：后台 task subagent 等待非误停）
  //   主 idle + 无 running 子会话 → stop + stopReason='session-idle'（自然编排间隙）
  //   主 running + STOPPED + stopReason='session-idle' → 定向自动 resume（主会话被唤醒即无缝续跑）
  //   stopReason='user-stop'（workflow_stop 权威急停）→ 永不自动恢复（Iter-22 权威停止语义保留）
  // Iter-23(A2) 修订——兜底检出"用户手工停"：主 idle 且末条回合终局=aborted(user) → 权威
  // user-stop（含级联打断子会话）。权威性高于 P1 守卫；undefined（探针故障）降级既有语义。
  // 闭环不变式：子会话在跑 ⇔ wf RUNNING → Start/派发必被拒 → 永无双 subAgent 同任务并发。
  // 仅在能判定 agent 状态时触发；CREATED/PENDING/COMPLETED/FAILED 不误改。
  async function syncInstanceState(cwd, instanceId) {
    const entry = await loadEntry(cwd, instanceId)
    if (!entry) return entry
    const sid = entry.meta.sessionId
    if (!sid || !isSessionLive(sid)) return entry // UNBOUND 或孤儿（孤儿由 Iter-18 回收）
    const running = isAgentRunning(sid)
    if (running === undefined || running === null) return entry // 无法判定，不触发
    const stage = entry.engine.snapshot().stage // 以引擎实际状态为准（hasState 仅缓存标记）
    if (running === false) {
      if (stage === 'RUNNING' && !isAgentPending(sid)) {
        // Iter-23(A2)：轮询兜底——先检未处置的"用户手工停"（A1 事件 tap 漏过时的恢复路径，
        // 如插件重启窗口）。命中 → 权威 user-stop（含级联打断子会话）。
        let userAbort = false
        try { userAbort = (await detectUserAbort(sid)) === true } catch (e) { userAbort = false }
        if (userAbort) {
          await applyUserStop(entry, cwd)
          return entry
        }
        // Iter-SUBA(P1)：会话树聚合守卫——有 running 子会话（如后台 task subagent）不得误停；
        // 探针失败降级为空（保持可停，不因探针故障卡死 RUNNING）。
        let childIds = []
        try { childIds = await listRunningChildren(sid) } catch (e) { childIds = [] }
        if (childIds.length > 0) return entry
        entry.engine.stop() // RUNNING→STOPPED，保 DONE 进度
        await entry.storage.save()
        entry.engine.setPersist('ok (session-idle sync)')
        // Iter-SUBA(P2)：自然编排间隙停 → 记 session-idle，供主会话活跃时定向自动恢复
        await patchMeta(cwd, instanceId, { stopReason: 'session-idle' })
      }
    } else if (stage === 'STOPPED' && entry.meta && entry.meta.stopReason === 'session-idle') {
      // Iter-SUBA(P2)：定向自动恢复——仅自然空闲停（session-idle）且主会话重新活跃时；
      // user-stop 永不自动恢复（权威停止）；resume 后清 stopReason（下轮不再误判）。
      entry.engine.resume() // STOPPED→RUNNING，保 DONE 进度
      await entry.storage.save()
      entry.engine.setPersist('ok (session-idle auto-resume)')
      await patchMeta(cwd, instanceId, { stopReason: null })
    }
    return entry
  }

  return {
    beginInstance,
    forSession,
    hydrateLatest,
    loadEntry,
    resolveEntry,
    listInstances,
    patchMeta,
    ensureWorkspaceSkeleton,
    checkWorkspaceTreeIntegrity,
    deriveSessionState,
    createBind,
    adoptInstance,
    recoverBindingConflicts,
    sessionBindState,
    scanOrphans,
    recoverOrphan,
    writeArchiveBackup,
    syncInstanceState,
    handleSessionUserStop, // Iter-23(A1)：mjs session/event tap 调用
    isAgentRunning,        // Iter-23(A3)：/wf/list stopHint 判定（webserver 路由用）
    listRunningChildren,   // Iter-23(A3)：/wf/list stopHint 判定（webserver 路由用）
    get,
    activeIdFor,
    sessionIdOf,
    sessionCwdOf,
    engines,
    activeBySession,
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { slugifyName, makeUuid8, instancesRootPath, instanceDirPath, archiveRootPath, archiveTimestamp, composeMetadata, createInstanceRegistry, isUserAbortTurnEnd, detectUserAbortFromLog }
}

// ---- module: tools-preset ----
// ============================================================================
// workflow-agent — Host 模型工具（preset 本地插件版）
// 文件：code/plugins/workflow-host-preset/tools-preset.js
// 说明：与 plugins/workflow-host/tools.js 相同的两个工具定义，但注册方式改为
//       ctx.tools.register（preset 本地 .mjs 插件形态，custom-bash.mjs /
//       dsh-tool-workflow 先例），而非动态插件的 harness.defineTool。
//       另外从 exec.agent.session.header.cwd 取会话工作区作为默认落盘根，
//       解决宿主插件无会话上下文时写错目录的问题。
// 依赖：ctx（fs/exec）、engine、storage、schema/parser 常量（同作用域内联）。
// ============================================================================

// ── 相对路径解析（复用 PoC 逐级上探逻辑）───────────────────────────────────
function parentDir(p) {
  const norm = p.replace(/\\/g, '/')
  const idx = norm.lastIndexOf('/')
  if (idx <= 0) return null
  return norm.slice(0, idx)
}

// 从 YAML 所在目录逐级向上探测，取第一个真实存在的拼接；兜底用 YAML 目录
async function resolveRel(fs, base, rel) {
  let d = base
  while (d) {
    const cand = d + '/' + rel.replace(/\\/g, '/')
    try {
      const st = await fs.stat(await fs.resolve(cand))
      if (st) return cand
    } catch (e) { /* keep climbing */ }
    d = parentDir(d)
  }
  return base + '/' + rel.replace(/\\/g, '/')
}

// ── ${param} 注入 ───────────────────────────────────────────────────────────
// PARAM_PATTERN 默认由同作用域 schema 模块提供；独立加载（Node 直测）时兜底
let E_PARAM_PATTERN = typeof PARAM_PATTERN !== 'undefined' ? PARAM_PATTERN : /\$\{(\w+)\}/g
// parseWorkflow 兜底：mjs 内联作用域有同名函数；Node 单独 require 时从 shared 加载
let E_parseWorkflow = typeof parseWorkflow !== 'undefined'
  ? parseWorkflow
  : (typeof require !== 'undefined' ? require('../../shared/workflow-parser').parseWorkflow : null)
function injectParams(value, params) {
  if (typeof value !== 'string') return value
  return value.replace(E_PARAM_PATTERN, (whole, key) => {
    if (params && params[key] !== undefined) return String(params[key])
    return whole // 未提供则保留原样，由调用方提示
  })
}

function injectArray(list, params) {
  return (list || []).map((x) => injectParams(x, params))
}

// v1.1：命名式 inputs 注入。值为 string → 注入后返回 string；
// 值为 string[] → 逐项注入后返回 string[]。
function injectInputsMap(map, params) {
  const out = {}
  for (const k of Object.keys(map || {})) {
    const v = map[k]
    out[k] = Array.isArray(v) ? v.map((x) => injectParams(x, params)) : injectParams(v, params)
  }
  return out
}

// 工作流文件加载：优先 workflowPath（读文件），兜底 workflowText（直接用）
async function loadWorkflowSource(fs, args) {
  if (args.workflowPath) {
    const p = String(args.workflowPath)
    const text = await fs.readText(await fs.resolve(p))
    return { text, base: p.replace(/[\\/][^\\/]*$/, '') }
  }
  if (args.workflowText) {
    return { text: String(args.workflowText), base: undefined }
  }
  return null
}

// ── 实例快照 instance.yaml 的注释头剥离（Iter-11：start/reset 读取实例定义）──
// 头部由 beginInstance 生成：连续 '#' 注释行 + 一个空行。剥离后即纯 YAML 定义。
function stripInstanceHeader(text) {
  const lines = String(text || '').split(/\r?\n/)
  let i = 0
  while (i < lines.length && lines[i].startsWith('#')) i++
  if (i > 0 && i < lines.length && lines[i].trim() === '') i++ // 头部结束空行
  return lines.slice(i).join('\n')
}

// 定义不合法错误（携带 workflowBeginErrors 数组，begin 路径保持既有契约）
function definitionError(errors) {
  const e = new Error('workflow 定义不合法: ' + errors.join('; '))
  e.workflowBeginErrors = errors
  return e
}

// ── 定义展开（Iter-11：begin/start/reset 共用）────────────────────────────
// src: { text, base }；params: 工作流级参数。返回 parsed（tasks 已注入参数、
// 解析相对路径、展开 loop/concurrent）。定义不合法或 items-from 为空时 throw。
async function expandDefinition(fs, src, params) {
  const parsed = E_parseWorkflow(src.text)
  if (parsed.errors && parsed.errors.length > 0) throw definitionError(parsed.errors)
  const p = params || {}
  const tasks = await Promise.all(parsed.tasks.map(async (t) => {
    const out = { ...t }
    out.inputs = injectInputsMap(t.inputsRaw, p)
    out.outputs = injectArray(t.outputsRaw, p)
    if (t.processorRaw) {
      const procRel = injectParams(t.processorRaw, p)
      out.processor = src.base ? await resolveRel(fs, src.base, procRel) : procRel
    }
    if (t.gateRaw) {
      const gateRel = injectParams(t.gateRaw, p)
      out.gate = {
        checker: src.base ? await resolveRel(fs, src.base, gateRel) : gateRel,
        onFailure: t.gateOnFailure,
        maxRetries: t.gateMaxRetries,
      }
    }
    if (t.itemsFromRaw) {
      const itemsRel = injectParams(t.itemsFromRaw, p)
      out.itemsFrom = src.base ? await resolveRel(fs, src.base, itemsRel) : itemsRel
      out.itemsFromRaw = t.itemsFromRaw // 保留原始值供循环展开二次注入
      out.itemVar = t.itemVar
    }
    return out
  }))
  parsed.tasks = tasks
  const finalTasks = []
  for (const t of tasks) {
    if (t.type === 'loop' && t.itemsFrom && t.itemVar) {
      const text = await fs.readText(await fs.resolve(t.itemsFrom))
      const items = text.split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith('#'))
      if (items.length === 0) throw new Error('循环 Task "' + t.id + '" 的 items-from 文件为空: ' + t.itemsFrom)
      const iterations = await expandLoopTasks(fs, t, items, t.itemVar, p)
      finalTasks.push(...iterations)
    } else if (t.type === 'concurrent' && t.itemsFrom && t.itemVar) {
      const text = await fs.readText(await fs.resolve(t.itemsFrom))
      const items = text.split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith('#'))
      if (items.length === 0) throw new Error('并发 Task "' + t.id + '" 的 items-from 文件为空: ' + t.itemsFrom)
      const iterations = await expandConcurrentTasks(fs, t, items, t.itemVar, p)
      finalTasks.push(...iterations)
    } else {
      finalTasks.push(t)
    }
  }
  parsed.tasks = finalTasks
  return parsed
}

// ── 循环展开：将 loop Task 展开为 N 个串行迭代实例 ────────────────────────
// items 参数：从 items-from 文件解析出的非空非注释行数组
// itemVar：迭代变量名（如 "module"），在 inputs/outputs 中解决 ${itemVar}
// params：已注入的工作流级参数
// loopTask：原始 loop Task 对象（含 inputsRaw/outputsRaw/processor/gate/dependsOn）
// prevDeps：【内部使用】前一个迭代的 id，用于构建串行依赖链
async function expandLoopTasks(fs, loopTask, items, itemVar, params) {
  const expanded = []
  const loopDeps = loopTask.dependsOn || []
  let prevId = null

  for (let i = 0; i < items.length; i++) {
    const item = String(items[i]).trim()
    if (!item) continue

    // 构建迭代参数（工作流 params + 当前 item）
    const iterParams = { ...params }
    iterParams[itemVar] = item

    // 安全 ID：loopTaskId/sanitized-item
    const sanitized = item.replace(/[^a-zA-Z0-9_\-]/g, '-').replace(/^-+|-+$/g, '') || ('iter-' + i)
    const iterId = loopTask.id + '/' + sanitized

    // inputs/outputs 重新注入（含 item 变量）
    const iterInputs = injectInputsMap(loopTask.inputsRaw || {}, iterParams)
    const iterOutputs = injectArray(loopTask.outputsRaw || [], iterParams)

    // processor 路径重新注入（含 item 变量——虽然通常不变）
    const iterProcessor = injectParams(loopTask.processor || '', iterParams)

    // gate 复制（同一 checker，独立执行）
    const iterGate = loopTask.gate ? {
      checker: loopTask.gate.checker,
      onFailure: loopTask.gate.onFailure,
      maxRetries: loopTask.gate.maxRetries,
    } : null

    expanded.push({
      id: iterId,
      name: (loopTask.name || loopTask.id) + ' - ' + item,
      type: 'llm-task',
      dependsOn: prevId ? [prevId] : loopDeps,
      timeout: loopTask.timeout || 600,
      processor: iterProcessor,
      inputs: iterInputs,
      outputs: iterOutputs,
      gate: iterGate,
      // 循环错误处理策略
      _onError: loopTask.onError || 'break',
      // 循环组元数据（供 Client DAG 分组渲染）
      _loopGroup: loopTask.id,
      _loopGroupName: loopTask.name || loopTask.id,
      _loopItem: item,
      _loopIndex: i,
    })
    prevId = iterId
  }

  return expanded
}

// Iter-8：并发展开——对 items 的每个 item 生成一个独立迭代，迭代之间无依赖（可并发，受组级 max 约束）
async function expandConcurrentTasks(fs, task, items, itemVar, params) {
  const expanded = []
  const loopDeps = task.dependsOn || []
  const gMax = task.maxConcurrency || items.length // 组级并发（默认 items 数量，全部并发）

  for (let i = 0; i < items.length; i++) {
    const item = String(items[i]).trim()
    if (!item) continue

    const iterParams = { ...params }
    iterParams[itemVar] = item

    const sanitized = item.replace(/[^a-zA-Z0-9_\-]/g, '-').replace(/^-+|-+$/g, '') || ('iter-' + i)
    const iterId = task.id + '/' + sanitized

    const iterInputs = injectInputsMap(task.inputsRaw || {}, iterParams)
    const iterOutputs = injectArray(task.outputsRaw || [], iterParams)
    const iterProcessor = injectParams(task.processor || '', iterParams)

    const iterGate = task.gate ? {
      checker: task.gate.checker,
      onFailure: task.gate.onFailure,
      maxRetries: task.gate.maxRetries,
    } : null

    expanded.push({
      id: iterId,
      name: (task.name || task.id) + ' - ' + item,
      type: 'llm-task',
      dependsOn: loopDeps, // ← 关键：无串行依赖链，都依赖原始前驱 → 可并发
      timeout: task.timeout || 600,
      processor: iterProcessor,
      inputs: iterInputs,
      outputs: iterOutputs,
      gate: iterGate,
      // 并发组元数据（Client DAG 分组渲染 + engine 组级并发控制）
      _concurrentGroup: task.id,
      _concurrentGroupName: task.name || task.id,
      _concurrentItem: item,
      _concurrentIndex: i,
      _concurrentMax: gMax,
    })
  }

  return expanded
}

// 从工具执行上下文取会话工作区（preset 挂载后 exec.agent 可用）
function sessionCwd(exec) {
  try {
    const cwd = exec && exec.agent && exec.agent.session && exec.agent.session.header && exec.agent.session.header.cwd
    return typeof cwd === 'string' && cwd.length > 0 ? cwd : undefined
  } catch (e) {
    return undefined
  }
}

// 注册工具：preset 本地插件形态（ctx.tools.register），不依赖 harness
// Iter-10：新增 registry 参数（instance-store 的 createInstanceRegistry 产物）。
//   - 会话上下文 + 无显式 statePath/workspaceRoot 参数 → 实例布局：
//     begin 时创建实例目录并绑定新 engine/storage；status 时按会话取活跃实例
//     （重启后惰性 hydrate）。快照附 instanceId 供调用方/前端识别。
//   - 显式 statePath/workspaceRoot 参数或无会话上下文 → 回退单实例绑定
//     （engine/storage 形参，保持既有行为与旧布局兼容）。
function registerWorkflowToolsPreset(ctx, engine, storage, registry) {
  const fs = ctx.get('fs')

  // ── 每次工具调用解析绑定的引擎/存储（避免跨会话闭包串扰，多会话并行安全）──
  async function bind(exec, args) {
    if (args && (args.statePath || args.workspaceRoot)) {
      return { engine, storage, instanceId: null }
    }
    if (registry) {
      const entry = await registry.forSession(exec)
      if (entry) return { engine: entry.engine, storage: entry.storage, instanceId: entry.instanceId }
    }
    return { engine, storage, instanceId: null }
  }

  function withInstanceId(snapshot, b) {
    if (b && b.instanceId) snapshot.instanceId = b.instanceId
    return snapshot
  }

  // ── workflow_begin ────────────────────────────────────────────────────────
  const beginTool = {
    name: 'workflow_begin',
    description: '解析并启动一个工作流定义（YAML）。参数 workflowPath 为本机绝对路径；或传 workflowText 直接给 YAML 文本。可选 params 对象注入工作流级 ${param} 模板变量。可选 workspaceRoot / statePath 指定状态落盘位置（兼容旧单实例布局）；默认在当前会话工作区创建实例目录 <cwd>/.workflow-agent/instances/<workflowName-uuid8>/（instance.yaml/state.json/metadata.json/output/logs），状态写入实例目录。成功返回解析出的任务列表（含处理技能绝对路径、门禁配置、instanceId）与初始 PENDING 状态；定义不合法时返回 errors 列表。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        workflowPath: { type: 'string', description: '工作流 YAML 的绝对路径' },
        workflowText: { type: 'string', description: '工作流 YAML 文本（与 workflowPath 二选一）' },
        workspaceRoot: { type: 'string', description: '（兼容旧布局）状态落盘根目录；默认走实例目录布局' },
        statePath: { type: 'string', description: '（兼容旧布局）完全自定义的状态文件绝对路径' },
        params: {
          type: 'object',
          additionalProperties: true,
          description: '工作流参数，替换字段中的 ${param_name}',
        },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) {
        return [{ type: 'text', text: JSON.stringify(v, null, 2) }]
      },
    },
    async execute(args, exec) {
      // 初始绑定（错误路径也要能落盘）
      let b = await bind(exec, args)
      try {
        if (!fs) throw new Error('fs service unavailable')
        if (args && args.workspaceRoot && b.storage) b.storage.setWorkspaceRoot(String(args.workspaceRoot))
        if (args && args.statePath && b.storage) b.storage.setStatePath(String(args.statePath))
        // 未显式指定 workspaceRoot 时，从会话上下文取工作区（legacy 单实例布局落点）
        if ((!args || !args.workspaceRoot) && b.storage) {
          const cwd = sessionCwd(exec)
          if (cwd) b.storage.setWorkspaceRoot(cwd)
        }
        const src = await loadWorkflowSource(fs, args)
        if (!src) throw new Error('需要 workflowPath 或 workflowText 参数')
        const params = (args && args.params) || {}
        let parsed
        try {
          parsed = await expandDefinition(fs, src, params)
        } catch (e) {
          if (e && e.workflowBeginErrors) {
            // 保持既有契约：解析错误经快照 workflowBeginErrors 字段返回
            b.engine.setError(e.message)
            await b.storage.save()
            const s = b.engine.snapshot()
            s.workflowBeginErrors = e.workflowBeginErrors
            return withInstanceId(s, b)
          }
          throw e
        }

        // ── Iter-10：多实例布局——成功路径创建实例目录并切换绑定 ──
        // （解析/展开失败不建实例目录；显式 statePath/workspaceRoot 参数走旧布局）
        if (registry && !args.statePath && !args.workspaceRoot) {
          const cwd = sessionCwd(exec)
          if (cwd) {
            const entry = await (registry.sessionIdOf(exec)
              ? registry.createBind(cwd, registry.sessionIdOf(exec), { // Iter-19：1:1 + CONFLICT 自愈
                workflowName: parsed.name,
                sourceText: src.text,
                sourcePath: args.workflowPath || null,
                params,
              })
              : registry.beginInstance({ cwd, sessionId: null, workflowName: parsed.name, sourceText: src.text, sourcePath: args.workflowPath || null, params }))
            b = { engine: entry.engine, storage: entry.storage, instanceId: entry.instanceId, recoveredConflict: entry._recoveredConflict || [] }
          }
        }

        b.engine.begin(parsed)
        b.engine.start() // Iter-19：begin 后即视为执行中 → RUNNING（与状态机一致）
        b.engine.setError(null)
        const r = await b.storage.save()
        b.engine.setPersist(r)
        const beginSnap = withInstanceId(b.engine.snapshot(), b)
        if (b.recoveredConflict && b.recoveredConflict.length > 0) beginSnap.recoveredConflict = b.recoveredConflict
        return beginSnap
      } catch (error) {
        b.engine.setError(error.message)
        await b.storage.save()
        return withInstanceId(b.engine.snapshot(), b)
      }
    },
  }
  ctx.tools.register(beginTool)

  // ── workflow_status ───────────────────────────────────────────────────────
  const statusTool = {
    name: 'workflow_status',
    description: '按编排进展更新工作流状态并同步持久化与 UI：stage（PENDING|RUNNING|COMPLETED|FAILED）、gateResult（PASS|FAIL）、task/tasktatus 更新单个任务（PENDING|RUNNING|DONE|FAILED|SKIPPED）、retries 重试计数、error 错误信息。状态写入当前会话活跃实例目录的 state.json（重启后自动从实例目录恢复）。每次调用返回最新快照（含 instanceId）。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        stage: { type: 'string', description: '全局阶段' },
        gateResult: { type: 'string', description: '门禁结果 PASS 或 FAIL' },
        task: { type: 'string', description: '要更新的任务 id' },
        taskStatus: { type: 'string', description: '该任务状态' },
        retries: { type: 'number', description: '失败重试计数' },
        error: { type: 'string', description: '错误信息' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) {
        return [{ type: 'text', text: JSON.stringify(v, null, 2) }]
      },
    },
    async execute(args, exec) {
      const b = await bind(exec, args)
      try {
        if (!args) args = {}
        if (args.stage) b.engine.setStage(String(args.stage))
        if (args.gateResult) b.engine.setGateResult(String(args.gateResult))
        if (typeof args.retries === 'number') b.engine.setRetries(args.retries)
        if (args.error !== undefined) b.engine.setError(args.error ? String(args.error) : null)
        if (args.task && args.taskStatus) {
          b.engine.updateTask(String(args.task), { status: String(args.taskStatus) })
        }
        const r = await b.storage.save()
        b.engine.setPersist(r)
        return withInstanceId(b.engine.snapshot(), b)
      } catch (error) {
        b.engine.setError(error.message)
        return withInstanceId(b.engine.snapshot(), b)
      }
    },
  }
  ctx.tools.register(statusTool)

  // ══ Iter-11：实例操控工具（操作当前会话工作区下的实例目录）══════════════
  // 定位语义：显式 instanceId → 本 cwd 实例目录精确解析；缺省 → 会话活跃实例。
  // 实例运行状态记实例目录 state.json；实例选择/切换由 DSH session 列表承担
  // （设计文档 §5.4）。

  // 实例定义的相对路径解析基目录（优先原始源定义所在目录）
  function instanceSourceBase(meta) {
    const sp = meta && meta.sourcePath
    if (sp && sp !== '(inline workflowText)') return sp.replace(/[\\/][^\\/]*$/, '')
    return undefined
  }

  // 读取实例 instance.yaml 并展开为 parsed（start/reset 共用）
  async function expandInstanceDefinition(entry) {
    const raw = await fs.readText(await fs.resolve(entry.dir + '/instance.yaml'))
    const text = stripInstanceHeader(raw)
    const params = (entry.meta && entry.meta.params) || {}
    return expandDefinition(fs, { text, base: instanceSourceBase(entry.meta) }, params)
  }

  // 条目是否有已落盘运行状态（一律以磁盘 state.json 为准，避免内存标记过期）
  async function entryStateOnDisk(entry) {
    try {
      const st = JSON.parse(await fs.readText(await fs.resolve(entry.dir + '/state.json')))
      return !!(st && st.workflow)
    } catch (e) {
      return false
    }
  }

  function errPayload(e) {
    const out = { error: (e && e.message) || String(e) }
    if (e && e.workflowBeginErrors) out.workflowBeginErrors = e.workflowBeginErrors
    return out
  }

  // ── workflow_list ─────────────────────────────────────────────────────────
  ctx.tools.register({
    name: 'workflow_list',
    description: '列出当前会话工作区下的全部 workflow 实例（按创建时间倒序）。phase=CREATED 表示仅创建未启动；READY 表示已有运行状态（stage/task 计数）。返回 {cwd, instances[], activeInstanceId}。',
    parameters: { type: 'object', additionalProperties: true, properties: {} },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        const cwd = registry.sessionCwdOf(exec)
        if (!cwd) throw new Error('无会话工作区（实例按 session cwd 隔离）')
        const instances = await registry.listInstances(cwd)
        const sid = registry.sessionIdOf(exec)
        // Iter-18：派生当前会话状态 UNBOUND/BOUND/DONE/BROKEN + 孤儿扫描提示
        let sessionState = null
        if (sid) sessionState = await registry.deriveSessionState(cwd, sid)
        const orphans = await registry.scanOrphans(cwd)
        const out = { cwd, instances, activeInstanceId: (sid && registry.activeIdFor(sid)) || null }
        if (sid) out.sessionState = sessionState
        if (orphans.length > 0) out.orphans = orphans.map(o => o.id)
        return out
      } catch (e) {
        return errPayload(e)
      }
    },
  })

  // ── workflow_create ───────────────────────────────────────────────────────
  ctx.tools.register({
    name: 'workflow_create',
    description: '从工作流定义（workflowPath 或 workflowText）+ params 创建 workflow 实例目录（instance.yaml/metadata.json/output/logs），校验定义但不启动执行。返回 {instanceId, dir, workflowName, phase:"CREATED"}。启动用 workflow_start。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        workflowPath: { type: 'string', description: '工作流 YAML 的绝对路径' },
        workflowText: { type: 'string', description: '工作流 YAML 文本（与 workflowPath 二选一）' },
        params: { type: 'object', additionalProperties: true, description: '工作流参数快照（启动时复用）' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        if (!fs) throw new Error('fs service unavailable')
        const cwd = registry.sessionCwdOf(exec)
        if (!cwd) throw new Error('无会话工作区（实例必须在会话工作区内创建）')
        const src = await loadWorkflowSource(fs, args)
        if (!src) throw new Error('需要 workflowPath 或 workflowText 参数')
        const parsed = E_parseWorkflow(src.text)
        if (parsed.errors && parsed.errors.length > 0) throw definitionError(parsed.errors)
        const entry = await (registry.sessionIdOf(exec)
          ? registry.createBind(cwd, registry.sessionIdOf(exec), { // Iter-19：1:1 + CONFLICT 自愈
            workflowName: parsed.name,
            sourceText: src.text,
            sourcePath: args.workflowPath || null,
            params: args.params || {},
          })
          : registry.beginInstance({ cwd, sessionId: null, workflowName: parsed.name, sourceText: src.text, sourcePath: args.workflowPath || null, params: args.params || {} }))
        return { instanceId: entry.instanceId, dir: entry.dir, workflowName: parsed.name, phase: 'CREATED', cwd, recoveredConflict: entry._recoveredConflict || [] }
      } catch (e) {
        return errPayload(e)
      }
    },
  })

  // ── workflow_start ────────────────────────────────────────────────────────
  ctx.tools.register({
    name: 'workflow_start',
    description: '启动一个已存在的 workflow 实例：读实例 instance.yaml → 解析展开 → 引擎置 PENDING → 写实例 state.json → 返回任务列表与 runnable（编排循环起点）。缺省 instanceId 时用当前会话活跃实例。RUNNING 中的实例会拒绝（先 stop 或 reset）。返回快照含 instanceId。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        instanceId: { type: 'string', description: '实例 id（缺省=当前会话活跃实例）' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        if (!fs) throw new Error('fs service unavailable')
        const entry = await registry.resolveEntry(exec, args && args.instanceId, { active: true })
        if (!entry) throw new Error('实例不存在' + (args && args.instanceId ? ': ' + args.instanceId : '（且当前会话无活跃实例，可先 workflow_create 或传 instanceId）'))
        // Iter-18：start 须会话已认领实例（UNBOUND→先 adopt；异会话→1:1 拒）
        const sessId = registry.sessionIdOf(exec)
        if (sessId && entry.meta.sessionId !== sessId) {
          if (!entry.meta.sessionId) throw new Error('实例 ' + entry.instanceId + ' 未绑定本会话；先用 workflow_adopt 采用')
          throw new Error('实例 ' + entry.instanceId + ' 已被会话 ' + entry.meta.sessionId + ' 占用（1:1），本会话不可启动')
        }
        // 状态机守卫
        const stage = entry.hasState ? entry.engine.snapshot().stage : 'CREATED'
        if (stage === 'RUNNING') throw new Error('实例 ' + entry.instanceId + ' 正在运行中（stage=RUNNING）')
        if (stage === 'STOPPED') throw new Error('实例 ' + entry.instanceId + ' 已停止；用 workflow_resume 续跑')
        if (stage === 'COMPLETED' || stage === 'FAILED') throw new Error('实例 ' + entry.instanceId + ' 已完成/失败（stage=' + stage + '）；用 workflow_reset 重跑')
        if (!entry.hasState) {
          const parsed = await expandInstanceDefinition(entry)
          entry.engine.begin(parsed)
        }
        entry.engine.setError(null)
        entry.engine.start() // Iter-18：PENDING→RUNNING（引擎守卫仅 PENDING）
        const r = await entry.storage.save()
        entry.engine.setPersist(r)
        entry.hasState = true
        const snap = entry.engine.snapshot()
        snap.instanceId = entry.instanceId
        return snap
      } catch (e) {
        return errPayload(e)
      }
    },
  })

  // ── workflow_stop ─────────────────────────────────────────────────────────
  ctx.tools.register({
    name: 'workflow_stop',
    description: '停止一个 workflow 实例：stage 置 STOPPED 并落盘实例 state.json（编排 Agent 看到 STOPPED 后不再推进）。缺省 instanceId 时用当前会话活跃实例。CREATED 未启动的实例无需停止。返回快照含 instanceId。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        instanceId: { type: 'string', description: '实例 id（缺省=当前会话活跃实例）' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        const entry = await registry.resolveEntry(exec, args && args.instanceId)
        if (!entry) throw new Error('实例不存在' + (args && args.instanceId ? ': ' + args.instanceId : '（且当前会话无活跃实例）'))
        if (!(await entryStateOnDisk(entry))) throw new Error('实例 ' + entry.instanceId + ' 尚未启动（CREATED），无需停止')
        entry.engine.stop() // Iter-18：仅 RUNNING→STOPPED（保进度，active=false）
        const r = await entry.storage.save()
        entry.engine.setPersist(r)
        // Iter-SUBA(P3)：权威急停——级联 interrupt 仍在跑的任务子会话（fire-and-return，one-shot/absent=no-op）；
        // apiProxy 不可用/单子失败均不阻断 stop 主流程。Iter-23(方向A)：手工停 DSH 会话路径（A1 事件
        // tap 即时处置 / A2 sync 轮询兜底）走 instance-store.applyUserStop，与本工具同一处置语义
        // （STOPPED(user-stop)+级联），面板 Stop 与 UI 停止按钮自此同级权威。
        let stoppedChildren = 0
        try {
          const sid = exec && exec.agent && exec.agent.session && exec.agent.session.header ? exec.agent.session.header.id : undefined
          const apiProxy = ctx && ctx.get ? ctx.get('apiProxy') : undefined
          if (apiProxy && apiProxy.subagents && sid) {
            const lst = await apiProxy.subagents.list({ rpcId: 'wf-stop-list-' + Date.now(), payload: { parentSessionId: sid } })
            const body = lst && lst.payload !== undefined ? lst.payload : lst
            const value = body && body.result && body.result.value ? body.result.value : body
            const entries = value && Array.isArray(value.entries) ? value.entries : []
            for (const ch of entries) {
              if (ch && ch.kind === 'child' && ch.activity === 'running') {
                try {
                  await apiProxy.subagents.interrupt({ rpcId: 'wf-stop-int-' + Date.now() + '-' + ch.id, payload: { parentSessionId: sid, childSessionId: ch.id } })
                  stoppedChildren += 1
                } catch (e2) { /* 单子失败不阻断 */ }
              }
            }
          }
        } catch (e2) { /* 级联失败不阻断 stop 主流程 */ }
        // Iter-SUBA(P2)：权威停止标记 user-stop——syncInstanceState 据此永不自动恢复（区别于自然空闲停）
        const cwd = sessionCwd(exec)
        if (cwd) await registry.patchMeta(cwd, entry.instanceId, { stopReason: 'user-stop' })
        const snap = entry.engine.snapshot()
        snap.instanceId = entry.instanceId
        snap.stopReason = 'user-stop'
        snap.stoppedChildren = stoppedChildren
        return snap
      } catch (e) {
        return errPayload(e)
      }
    },
  })

  // ── workflow_reset ────────────────────────────────────────────────────────
  ctx.tools.register({
    name: 'workflow_reset',
    description: '重置一个 workflow 实例并可直接重跑：从实例 instance.yaml 重新解析展开 → 引擎全新 PENDING → 覆盖实例 state.json → metadata 记 lastResetAt → 返回新快照与 runnable（等效清空状态重跑；output/logs 产物文件保留，同名输出会被覆盖）。缺省 instanceId 时用当前会话活跃实例。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        instanceId: { type: 'string', description: '实例 id（缺省=当前会话活跃实例）' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        if (!fs) throw new Error('fs service unavailable')
        const cwd = registry.sessionCwdOf(exec)
        if (!cwd) throw new Error('无会话工作区')
        const entry = await registry.resolveEntry(exec, args && args.instanceId, { active: true })
        if (!entry) throw new Error('实例不存在' + (args && args.instanceId ? ': ' + args.instanceId : '（且当前会话无活跃实例）'))
        // Iter-18：reset 仅 STOPPED/COMPLETED/FAILED（PENDING/CREATED/RUNNING 拒）
        const stage = entry.hasState ? entry.engine.snapshot().stage : 'CREATED'
        if (stage === 'RUNNING') throw new Error('reset 仅允许 STOPPED/COMPLETED/FAILED；RUNNING 先 workflow_stop')
        if (stage === 'CREATED' || stage === 'PENDING') throw new Error('reset 仅允许 STOPPED/COMPLETED/FAILED（当前 ' + stage + '）')
        // Iter-18：先写 reset 归档备份（<ts>_reset_<state>/），再 engine.reset()
        const backupDir = await registry.writeArchiveBackup(cwd, entry.instanceId, 'reset', (stage || 'UNKNOWN'))
        // Iter-22：reset 不依赖内存 state.def（hydrate 不恢复 def，历史/重启/hydrate-only 实例
        // 必无 def）——从 instance.yaml 重新解析展开定义再重置，任意可 reset 实例都能重跑。
        const parsed = await expandInstanceDefinition(entry)
        entry.engine.resetWithDefinition(parsed) // → 全新 PENDING
        entry.engine.setError(null)
        const r = await entry.storage.save()
        entry.engine.setPersist(r)
        await registry.patchMeta(cwd, entry.instanceId, { lastResetAt: new Date().toISOString(), stopReason: null }) // Iter-SUBA(P2)：重置即全新运行，清除停止标记
        const snap = entry.engine.snapshot()
        snap.instanceId = entry.instanceId
        snap.resetNote = '状态已重置（output/logs 产物保留，同名文件将被覆盖）'
        snap.resetBackup = backupDir
        return snap
      } catch (e) {
        return errPayload(e)
      }
    },
  })

  // ── workflow_resume（Iter-18 新增：仅 STOPPED 续跑）────────────────────────
  ctx.tools.register({
    name: 'workflow_resume',
    description: '续跑一个已停止（STOPPED）的 workflow 实例：engine.resume() 从已存 state.json hydrate 续跑保进度（保 DONE）→ RUNNING。缺省 instanceId 用当前会话活跃实例。仅 STOPPED 可 resume；PENDING/RUNNING/COMPLETED/FAILED 拒绝。返回快照含 instanceId。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        instanceId: { type: 'string', description: '实例 id（缺省=当前会话活跃实例）' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        const entry = await registry.resolveEntry(exec, args && args.instanceId)
        if (!entry) throw new Error('实例不存在' + (args && args.instanceId ? ': ' + args.instanceId : '（且当前会话无活跃实例）'))
        if (!(await entryStateOnDisk(entry))) throw new Error('实例 ' + entry.instanceId + ' 尚未启动（CREATED），无进度可续跑')
        const stage = entry.engine.snapshot().stage
        if (stage !== 'STOPPED') throw new Error('resume 仅允许 STOPPED（当前 ' + stage + '）')
        entry.engine.resume() // STOPPED→RUNNING，保 DONE
        const r = await entry.storage.save()
        entry.engine.setPersist(r)
        // Iter-SUBA(P2)：显式 resume 清 stopReason（自动恢复语义只对 session-idle 生效，防残留误判）
        const cwdResume = sessionCwd(exec)
        if (cwdResume) await registry.patchMeta(cwdResume, entry.instanceId, { stopReason: null })
        const snap = entry.engine.snapshot()
        snap.instanceId = entry.instanceId
        return snap
      } catch (e) {
        return errPayload(e)
      }
    },
  })

  // ── workflow_adopt（Iter-18 新增：采用池中 UNBOUND 实例并绑定本会话）────────
  ctx.tools.register({
    name: 'workflow_adopt',
    description: '采用一个池中 UNBOUND（sessionId==null）的 workflow 实例并绑定到当前会话（1:1 守卫；RUNNING 实例先 stop 再采用）。须传 instanceId。返回实例快照含 instanceId 与 adopted=true。',
    parameters: {
      type: 'object',
      additionalProperties: true,
      properties: {
        instanceId: { type: 'string', description: '要采用的实例 id（必填）' },
      },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render(_a, v) { return [{ type: 'text', text: JSON.stringify(v, null, 2) }] },
    },
    async execute(args, exec) {
      try {
        if (!registry) throw new Error('registry unavailable')
        if (!fs) throw new Error('fs service unavailable')
        const cwd = registry.sessionCwdOf(exec)
        if (!cwd) throw new Error('无会话工作区（实例必须在会话工作区内采用）')
        if (!(args && args.instanceId)) throw new Error('workflow_adopt 须传 instanceId')
        const sessId = registry.sessionIdOf(exec)
        if (!sessId) throw new Error('无会话 id，无法绑定实例')
        const entry = await registry.adoptInstance(cwd, sessId, args.instanceId)
        const snap = entry.engine.snapshot()
        snap.instanceId = entry.instanceId
        snap.adopted = true
        snap.meta = entry.meta
        return snap
      } catch (e) {
        return errPayload(e)
      }
    },
  })
}

